class MySprite extends AnimatedSprite {
  public MySprite() {
    this.addAnimation("idle", "bunny1_walk%d", 2);
  }

  public void run() {
    this.playAnimation("idle");
    if (this.isKeyPressed(KeyCode.S)) {
      this.setAnimationInterval(60);
    } else if (this.isKeyPressed(KeyCode.W)) {
      this.setAnimationInterval(10);
    }
  }
}

class MyStage extends Stage {
  public MyStage() {
    this.add(new MySprite());
  }
}

void main() {
  Stage myStage = new Stage(600, 240);
  AnimatedSprite mySprite = new AnimatedSprite();
