void main() {
  Stage myStage = new Stage(600, 240);

  Color myColor = new Color();
  // Only the hue, which keeps the saturation and the brightness as they were.
  myColor.setHSB(140);
  myStage.setColor(myColor);
  myStage.wait(2000);
  // Hue, saturation and brightness at once: a pale, dark green.
  myColor.setHSB(140, 80, 120);
  myStage.setColor(myColor);
}

void main() {
  Stage myStage = new Stage(600, 240);

  Color myColor = new Color();
  myColor.setRGB(30, 120, 220);
  myStage.setColor(myColor);
  System.out.println("That colour has the hue " + myColor.getH() + ".");
}

void main() {
  Stage myStage = new Stage(600, 240);
  Sprite mySprite = new Sprite("slime", "slimeGreen");
  myStage.add(mySprite);

  // Printing a colour tells you which one it is - the first thing worth
  // trying when a tint does not look the way it should.
  mySprite.setTint(255, 128, 0);
  System.out.println(mySprite.getTint());

  Color orange = new Color(255, 128, 0);
  System.out.println("Same colour? " + orange.equals(mySprite.getTint()));
}

void main() {
  Stage myStage = new Stage(600, 240);
  myStage.setDebug(true);
  Sprite mySprite = new Sprite("slime", "slimeGreen");
  myStage.add(mySprite);

  // A flattened circle, given by the box it fits into.
  mySprite.setHitbox(new Ellipse(-25, -15, 50, 30));
}

void main() {
  Stage myStage = new Stage(600, 240);
  myStage.setDebug(true);
  Sprite mySprite = new Sprite("slime", "slimeGreen");
  myStage.add(mySprite);

  // A hitbox of its own, from a shape or from a list of corners. A sprite
  // builds one from its costume, so this is only needed to check a shape by
  // hand.
  Hitbox fromShape = new Hitbox(new Circle(0, 0, 30));
  double[] x = { -20, 20, 20, -20 };
  double[] y = { -20, -20, 20, 20 };
  Hitbox fromPoints = new Hitbox(x, y);
  System.out.println("they overlap: " + fromShape.intersects(fromPoints));
}

void main() {
  Stage myStage = new Stage(600, 240);
  myStage.setDebug(true);
  Sprite mySprite = new Sprite("slime", "slimeGreen");
  myStage.add(mySprite);

  Hitbox myHitbox = mySprite.getHitbox();
  // Whether a point is inside the sprite - the same question isTouchingMousePointer()
  // asks, but about any point at all.
  while (true) {
    myStage.display("mouse inside: " + myHitbox.contains(myStage.getMouseX(), myStage.getMouseY()));
    myStage.wait(50);
  }
}

void main() {
  Stage myStage = new Stage(600, 240);
  myStage.setDebug(true);
  Sprite mySprite = new Sprite("slime", "slimeGreen");
  myStage.add(mySprite);

  Bounds myBounds = mySprite.getHitbox().getBounds();
  // The smallest upright rectangle the hitbox fits into.
  System.out.println("x " + myBounds.x() + ", y " + myBounds.y());
  System.out.println("width " + myBounds.width() + ", height " + myBounds.height());
}

void main() {
  Stage myStage = new Stage(600, 240);
  myStage.setDebug(true);
  Sprite mySprite = new Sprite("slime", "slimeGreen");
  myStage.add(mySprite);

  Hitbox myHitbox = mySprite.getHitbox();
  // The shape the hitbox is made of, in the place the sprite currently is.
  Shape myShape = myHitbox.getShape();
  System.out.println("the sprite covers " + myShape.getBounds().width() + " pixels across");
}

void main() {
  Stage myStage = new Stage(600, 240);
  myStage.setDebug(true);
  Sprite green = new Sprite("green", "slimeGreen");
  green.setX(-150);
  myStage.add(green);

  Sprite blue = new Sprite("blue", "slimeBlue");
  myStage.add(blue);

  // Whether two hitboxes overlap, which is what isTouchingSprite() asks.
  while (true) {
    green.changeX(4);
    green.ifOnEdgeBounce();
    myStage.display("touching: " + green.getHitbox().intersects(blue.getHitbox()));
    myStage.wait(30);
  }
}

void main() {
  Stage myStage = new Stage(600, 240);
  myStage.setDebug(true);
  Sprite mySprite = new Sprite("slime", "slimeGreen");
  myStage.add(mySprite);

  Hitbox myHitbox = new Hitbox(new Rectangle(-20, -10, 40, 20));
  // Puts the shape where a sprite of that position, direction and size would
  // be. The sprite does this for its own hitbox every frame.
  myHitbox.translateAndRotateAndResize(45, 0, 0, 100, 50, 200);
  System.out.println("the moved hitbox sits at " + myHitbox.getBounds().x());
}

void main() {
  Stage myStage = new Stage(600, 240);

