  myStage.setColor(HtmlColor.CORNFLOWER_BLUE);
  myStage.wait(1500);
  myStage.setColor(HtmlColor.TOMATO);
  myStage.wait(1500);
  myStage.setColor(HtmlColor.MEDIUM_SEA_GREEN);
}

void main() {
