  // With the pen down every move draws a line. Lifting it up moves the pen
  // without leaving anything behind, which is how a drawing gets a gap.
  while (true) {
    myPen.setPosition(-200, 0);
    myPen.down();
    myPen.setPosition(-60, 0);
    myPen.up();

    myPen.setPosition(60, 0);
    myPen.down();
