void main() {
  Stage myStage = new Stage(600, 240);
  Sprite mySprite = new Sprite("slime", "slimeGreen");
  myStage.add(mySprite);

  mySprite.getShaders().add("grayscale", "assets/grayscale.frag", null);
  mySprite.getShaders().add("invert", "assets/invert.frag", null);

  while (true) {
    mySprite.say(mySprite.getShaders().getCurrentName());
    myStage.wait(1000);
    // after the last shader comes the first one again
    mySprite.getShaders().next();
  }
}

void main() {
  Stage myStage = new Stage(600, 240);
  Sprite mySprite = new Sprite("slime", "slimeGreen");
  myStage.add(mySprite);

  mySprite.getShaders().add("invert", "assets/invert.frag", null);

  while (true) {
    myStage.wait(1000);
    // back to the plain costume; the shader is kept for later
    mySprite.getShaders().reset();
    myStage.wait(1000);
    mySprite.getShaders().switchTo("invert");
  }
}

void main() {
  Stage myStage = new Stage(600, 240);
  Sprite mySprite = new Sprite("slime", "slimeGreen");
  myStage.add(mySprite);

  // the first shader added is the one drawn with
  mySprite.getShaders().add("grayscale", "assets/grayscale.frag", null);
  mySprite.getShaders().add("invert", "assets/invert.frag", null);

  while (true) {
    if (mySprite.isMouseDown()) {
      mySprite.getShaders().switchTo("invert");
    } else {
      mySprite.getShaders().switchTo("grayscale");
    }
    myStage.wait(20);
  }
}
